import { Dispatch, SetStateAction } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';
import { CalendarList, LocaleConfig } from 'react-native-calendars';

LocaleConfig.locales['zh-tw'] = {
  monthNames: ['一月','二月','三月','四月','五月','六月','七月','八月','九月','十月','十一月','十二月'],
  monthNamesShort: ['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'],
  dayNames: ['星期日','星期一','星期二','星期三','星期四','星期五','星期六'],
  dayNamesShort: ['日','一','二','三','四','五','六'],
  today: '今天'
};

LocaleConfig.defaultLocale = 'zh-tw';

type data = {
    [key: string]: {
        value: number,
        isFuture: boolean,
        timestamp: number,
    }
};
type CalendarProps = {
    data: data;
    controller: [boolean, Dispatch<SetStateAction<boolean>>];
    dateAction: (e: any, d: { year: number; month: number; day: number; timestamp?: number; totalValue?: number }) => void;
    dayColor?: string;
    monthColor?: string;
};

export default function Calendar(props: CalendarProps) {
    const [open, setOpen] = props.controller;
    const currentTimestamp = Math.floor(new Date().getTime() / 1000);
    const data = props.data;
    const dayColor = props.dayColor ? props.dayColor : '#6b7280';
    const dateAction = props.dateAction;
    
    if (!open) return null;

    return (
        <View style={styles.container}>
            <CalendarList
                pastScrollRange={12}
                futureScrollRange={1}
                scrollEnabled={true}
                showScrollIndicator={false}
                // style={styles.calender}
                calendarStyle={styles.calender}
                
                
                dayComponent={({ date, state }) => {
                    if (!date || state === 'disabled') {
                        return <View style={{ width: '100%', height: 50 }} />;
                    }

                    const record = data[date.dateString];
                    const value = record ? record.value : null;
                    const isFuture = record ? record.isFuture : (new Date(date.dateString).getTime() / 1000 > currentTimestamp);

                    return (
                        <Pressable
                            style={{
                                width: '100%',
                                height: 50,
                                alignItems: 'center',
                                justifyContent: 'center',
                                paddingVertical: 8,
                                borderRadius: 8,
                                backgroundColor: isFuture ? '#6b7280' : dayColor,
                            }}
                            onPress={(e) => {
                                let d = { 
                                    year: date.year, 
                                    month: date.month, 
                                    day: date.day,
                                };
                                dateAction(e, d);
                            }}
                        >
                            <Text style={{ textAlign: 'center', fontSize: 20, color: '#ffffff' }}>
                                {date.day}
                            </Text>
                            
                            {value !== null && (
                                <Text style={{ textAlign: 'center', fontSize: 10, color: '#22c55e' }}>
                                    {value}
                                </Text>
                            )}
                        </Pressable>
                    );
                }}
                
                theme={{
                    calendarBackground: 'transparent',
                    textSectionTitleColor: '#ffffff',
                    monthTextColor: '#ffffff',
                    textMonthFontSize: 20,
                    'stylesheet.calendar-list.main': {
                        flatListContainer: {
                            flex: 1,
                            overflow: 'hidden',
                            width: '100%',
                            height: '100%',
                        }
                    },
                } as any}
            />
        </View>
    );
};

const styles = StyleSheet.create({
    container: {
        backgroundColor: 'rgba(107, 114, 128, 0.7)',
        alignItems: 'center',
        justifyContent: 'center',
        flex: 1,
        width: '100%',
    },
    calender: {
        width: '100%',
    }
});